    return bg,T,Th
def f(I):
    bg,T,Th=analyze(I); h,w=len(I),len(I[0])
    dist={s:0 for s in T}; par={}; q=collections.deque(sorted(T)); endpoint=None
    while q:
        v=q.popleft(); r,c=v
        for dr,dc in ((0,-1),(0,1),(-1,0),(1,0)):
            n=(r+dr,c+dc)
            if n in Th: endpoint=n; break
            if 0<=n[0]<h and 0<=n[1]<w and I[n[0]][n[1]]==bg and n not in dist:
                dist[n]=dist[v]+1; par[n]=v; q.append(n)
        if endpoint is not None: break
    O=[row[:] for row in I]
    u=endpoint
    while u is not None:
        if u not in T and u not in Th: O[u[0]][u[1]]=3
        u=par.get(u)
    return O
